// tb.v: random-stimulus testbench for Counter, generated by tests/unit/test_emit.c.
// Prints the outputs every cycle; test_emit compares them with the Tern simulator.
`timescale 1ns/1ps
module tb;
    reg clk = 1'b0;
    reg rst = 1'b0;
    reg en = 1'b0;
    reg load = 1'b0;
    reg [7:0] din = 8'd0;
    wire [7:0] count;
    reg [9:0] stim [0:239];
    integer i;

    Counter dut (
        .clk(clk),
        .rst(rst),
        .en(en),
        .load(load),
        .din(din),
        .count(count)
    );

    task cycle_clk;
        begin
            clk = 1'b1;
            #5;
            clk = 1'b0;
            #5;
        end
    endtask

    task do_reset;
        begin
            rst = 1'b1;
            #1;
            cycle_clk;
            cycle_clk;
            rst = 1'b0;
            #1;
        end
    endtask

    initial begin
        $readmemh("stim.hex", stim);
        #1;
        for (i = 0; i < 240; i = i + 1) begin
            if (i == 0 || i == 120)
                do_reset;
            {en, load, din} = stim[i];
            #1;
            $display("D %0d %h", i, count);
            cycle_clk;
        end
        $finish;
    end
endmodule
